changeSet.sql:
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '${adminRole}') THEN
        CREATE ROLE ${adminRole} LOGIN PASSWORD '${adminPass}' NOSUPERUSER NOBYPASSRLS;
    END IF;
END
$$;

GRANT USAGE ON SCHEMA nexus TO ${adminRole};
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA nexus TO ${adminRole};
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA nexus TO ${adminRole};

-- nexus-4a8pn case (f): the reproduction toggles FORCE RLS on
-- topic_assignments via nexus_test.set_force_rls (PgContainerHelper's typed
-- wrapper, see that method's own javadoc) -- a plain LOGIN role has no USAGE
-- on nexus_test by default, same gap db.changelog-test-role.xml's own
-- fts_matches grant closes for svcRole.
GRANT USAGE ON SCHEMA nexus_test TO ${adminRole};
GRANT EXECUTE ON FUNCTION nexus_test.set_force_rls(regclass, boolean) TO ${adminRole};

ALTER TABLE nexus.topic_assignments OWNER TO ${adminRole};

-- nexus-l3yuc.1 (RDR-207 memory-004): MemorySummariesRlsTest reads nexus.memory
-- and nexus.memory_summaries AS THE OWNER with a second tenant's GUC stamped, so
-- a missing FORCE ROW LEVEL SECURITY (the flag that makes the owner subject to
-- the policy) shows up as a cross-tenant read. It also flips FORCE off and on
-- through nexus_test.set_force_rls to prove the assertion is sensitive, which
-- only the owner may do. Both tables transfer to ${adminRole} for that reason;
-- the sequences they own (memory_id_seq, memory_summaries_id_seq) follow.
ALTER TABLE nexus.memory OWNER TO ${adminRole};
ALTER TABLE nexus.memory_summaries OWNER TO ${adminRole};
